const response = $input.first().json;
const fail = (code, message, status = null) => [{ json: {
  ids: [], errors: [{ id: null, code, message, status }]
} }];

if (response.error) {
  return fail('NETWORK_ERROR', 'Не удалось получить список сделок: ошибка соединения или тайм-аут.');
}

const status = Number(response.statusCode);
let body;
try {
  body = JSON.parse(response.body);
} catch {
  return fail('INVALID_JSON', 'API вернул некорректный JSON вместо списка сделок.', status);
}

if (status < 200 || status >= 300 || !Number.isInteger(status)) {
  return fail('HTTP_ERROR', typeof body?.error === 'string'
    ? body.error.slice(0, 300) : `Не удалось получить список сделок. HTTP ${status}.`, status);
}
if (!Array.isArray(body?.result?.deals)) {
  return fail('INVALID_RESPONSE', 'В ответе API нет массива result.deals.', status);
}

const ids = [];
const errors = [];
const seen = new Set();
for (const [index, id] of body.result.deals.entries()) {
  if (!Number.isSafeInteger(id) || id <= 0) {
    errors.push({ id: null, code: 'INVALID_ID', message: `В списке сделок неверный ID в позиции ${index + 1}.` });
    continue;
  }
  // Одинаковую сделку достаточно запросить один раз.
  if (!seen.has(id)) {
    seen.add(id);
    ids.push(id);
  }
}
return [{ json: { ids, errors } }];

const data = [];
const errors = [...$('Проверить список').first().json.errors];
const validId = value => Number.isSafeInteger(value) && value > 0;
const validParty = value => value && validId(value.id) && typeof value.name === 'string';

for (const [index, item] of $input.all().entries()) {
  // Берем исходный ID по связи элементов, в том числе при сетевой ошибке.
  const id = $('Подготовить ID').itemMatching(index).json.id;
  const response = item.json;
  const addError = (code, message, status = null) => errors.push({ id, code, message, status });

  if (response.error) {
    addError('NETWORK_ERROR', 'Ошибка соединения с API или превышено время ожидания.');
    continue;
  }

  const status = Number(response.statusCode);
  let body;
  try {
    body = JSON.parse(response.body);
  } catch {
    addError('INVALID_JSON', 'API вернул некорректный JSON.', status);
    continue;
  }

  if (!Number.isInteger(status) || status < 200 || status >= 300 || body?.error) {
    addError('HTTP_ERROR', typeof body?.error === 'string'
      ? body.error.slice(0, 300) : `Не удалось загрузить сделку. HTTP ${status}.`, status);
    continue;
  }

  const deal = body?.result;
  if (!deal || deal.id !== id || typeof deal.title !== 'string'
      || typeof deal.amount !== 'number' || !Number.isFinite(deal.amount)
      || !validParty(deal.responsible) || !validParty(deal.company)) {
    addError('INVALID_RESPONSE', 'В ответе API отсутствуют обязательные поля или не совпадает ID.', status);
    continue;
  }

  // Отдаем только поля, которые нужны странице.
  data.push({
    id: deal.id,
    title: deal.title,
    amount: deal.amount,
    responsible: { id: deal.responsible.id, name: deal.responsible.name },
    company: { id: deal.company.id, name: deal.company.name }
  });
}

return [{ json: {
  success: errors.length === 0,
  total: data.length,
  data,
  errors
} }];
